        RAISE_APPLICATION_ERROR(
            -20001,
            ''Patient ID, Slot ID and Booking Source are required''
        );
    END IF;

    GIRISH_BOOK_APPOINTMENT(
        P_PATIENT_ID => V_PATIENT_ID,
        P_SLOT_ID => V_SLOT_ID,
        P_BOOKING_SOURCE => V_BOOKING_SOURCE,
        P_APPOINTMENT_REF => V_APPOINTMENT_REF
    );

    COMMIT;

    HTP.P(
