      p_items_per_page =>  0,
      p_mimes_allowed  => '',
      p_comments       => NULL,
      p_source         => 
'SELECT
    d.department_name,
    doc.first_name || '' '' || doc.last_name AS doctor_name,
    COUNT(s.slot_id) AS total_slots,
    SUM(s.max_patients_per_slot) AS total_capacity,
    SUM(s.booked_patients) AS total_booked,
    ROUND(AVG(s.booked_patients / NULLIF(s.max_patients_per_slot, 0)) * 100, 2) AS avg_utilisation_pct
FROM GIRISH_SLOTS s
JOIN GIRISH_SLOT_TEMPLATES st ON s.template_id = st.template_id
JOIN GIRISH_DOCTORS doc ON st.doctor_id = doc.doctor_id
JOIN GIRISH_DEPARTMENTS d ON doc.department_id = d.department_id
WHERE TRUNC(s.slot_date) >= TRUNC(SYSDATE)
GROUP BY d.department_name, doc.first_name, doc.last_name
ORDER BY avg_utilisation_pct DESC NULLS LAST'
      );
