      p_module_name    => 'girish_opd_api',
      p_pattern        => 'slots',
      p_method         => 'GET',
      p_source_type    => 'json/collection',
      p_items_per_page =>  0,
      p_mimes_allowed  => '',
      p_comments       => NULL,
      p_source         => 
'SELECT slot_id,
       template_id,
       slot_date,
       start_time,
       end_time,
       max_patients_per_slot,
       booked_patients,
       status
FROM GIRISH_SLOTS
ORDER BY slot_date, start_time'
      );
  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'girish_opd_api',
      p_pattern        => 'token_queue',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);
  ORDS.DEFINE_HANDLER(
      p_module_name    => 'girish_opd_api',
      p_pattern        => 'token_queue',
      p_method         => 'GET',
      p_source_type    => 'json/collection',
      p_items_per_page =>  0,
      p_mimes_allowed  => '',
      p_comments       => NULL,
      p_source         => 
'SELECT
    q.queue_id,
    q.appointment_id,
    a.appointment_ref,
    q.department_id,
    d.department_name,
    q.queue_date,
    q.token_number,
    q.status,
    q.created_on
FROM GIRISH_TOKEN_QUEUE q
JOIN GIRISH_APPOINTMENTS a
    ON a.appointment_id = q.appointment_id
JOIN GIRISH_DEPARTMENTS d
    ON d.department_id = q.department_id
ORDER BY q.queue_date DESC, q.token_number'
      );


  COMMIT; 
END;